style.css:
@-moz-document domain("youtube.com"), domain("music.youtube.com") {
/* ==========================================================================
     YOUR CUSTOM UI: THE SUPERIOR BUILD
     - Split-Card Design (Flat bottom thumbnails + Glass text boxes)
     - Hardware Accelerated Animations (Zero Filter Lag)
     - Fixed Text Overlaps & Restored Submit Buttons
     ========================================================================== */

  /* --- 1. THE SPLIT-CARD DESIGN (Your core aesthetic) --- */
  /* Top Half: Thumbnail with flat bottom */
  .yt-core-image--content-mode-scale-aspect-fill {
      object-fit: cover;
      border-radius: 1em !important;
  }
  
  ytd-thumbnail #thumbnail.ytd-thumbnail {
      border-top-left-radius: 1em !important;
      border-top-right-radius: 1em !important;
      border-bottom-left-radius: 0px !important; 
      border-bottom-right-radius: 0px !important;
      overflow: hidden;
  }

  /* Bottom Half: The 28px Frosted Text Box */
  #details.ytd-rich-grid-media, 
  #details.ytd-grid-video-renderer, 
  #details.ytd-rich-grid-slim-media, 
  #card-title.ytd-search-refinement-card-renderer,
  .details.ytd-compact-video-renderer {
      background-color: rgba(0, 0, 0, 0.4);
      backdrop-filter: blur(28px) !important;
      -webkit-backdrop-filter: blur(28px) !important;
      border: 1px solid #ffffff12;
      border-top: none;
      border-bottom-left-radius: 1em;
      border-bottom-right-radius: 1em;
      padding: 12px !important;
      
      /* FIXED: Removed your negative margins that caused overlapping */
      margin-top: 0px !important; 
      margin-left: 0px !important;
      z-index: 1;
      position: relative;
  }

  /* Clean up sidebar padding */
  .metadata.ytd-compact-video-renderer {
      margin-left: 0px !important;
  }
  #avatar-link.ytd-rich-grid-media {
      margin-left: 0px !important;
      margin-right: 12px !important;
  }

  /* --- 2. POPUPS, DIALOGS & MENUS (Your 2em styling) --- */
  .ytp-popup, 
  #emojis.ytd-commentbox, 
  .ytp-sfn, 
  .ytp-ad-preview-container, 
  .ytp-ad-message-container,
  ytd-menu-popup-renderer, 
  ytd-video-preview, 
  #contentWrapper.tp-yt-iron-dropdown > *, 
  tp-yt-paper-dialog {
      background-color: #00000069 !important;
      backdrop-filter: blur(28px) !important;
      -webkit-backdrop-filter: blur(28px) !important;
      border-radius: 2em !important;
      border: 1px solid #ffffff12 !important;
      box-shadow: 0 10px 30px rgba(0,0,0,0.5) !important;
  }

  /* Your MenuPop Animation - Hardware Accelerated */
  @keyframes MenuPop {
    0%   { transform: scale(0.9); opacity: 0; }
    100% { transform: scale(1); opacity: 1; }
  }
  
  ytd-menu-popup-renderer {
    animation: MenuPop 0.25s cubic-bezier(0.16, 1, 0.3, 1) forwards !important;
    transform: translateZ(0); /* Fixes jitter */
    overflow: hidden;
  }

  /* --- 3. MASTHEAD, SEARCH & CHIPS BAR --- */
  #masthead-container.ytd-app, #background.ytd-masthead {
      background: transparent !important;
  }

  ytd-masthead {
      background-color: rgba(0, 0, 0, 0.4) !important;
      backdrop-filter: blur(28px) !important;
      -webkit-backdrop-filter: blur(28px) !important;
      border-bottom: 1px solid #ffffff24 !important;
  }

  #container.ytd-searchbox, #search-icon-legacy.ytd-searchbox {
      background-color: var(--yt-spec-badge-chip-background) !important;
      border: none !important;
  }

  #voice-search-button.ytd-masthead {
      background-color: var(--yt-spec-badge-chip-background) !important;
  }

  /* Fixed Chips Bar (Floating pill without breaking layout) */
  #scroll-container.ytd-feed-filter-chip-bar-renderer {
      margin: 10px auto !important; 
      padding: 4px 15px !important;
      backdrop-filter: blur(28px) !important;
      -webkit-backdrop-filter: blur(28px) !important;
      border-radius: 3em !important;
      background-color: rgba(0, 0, 0, 0.47) !important;
      border: 1px solid #ffffff12 !important;
      width: fit-content !important; 
  }
  
  #chips-wrapper.ytd-feed-filter-chip-bar-renderer {
      background-color: transparent !important;
  }

  /* --- 4. BADGES, SIDEBAR & PLAYER --- */
  ytd-thumbnail-overlay-time-status-renderer, 
  ytd-thumbnail-overlay-button-renderer {
      background: #0f0f0f4f !important;
      border-radius: 1em !important;
      border: 0.5px solid #ffffff2e !important;
      margin-bottom: 8px !important;
      backdrop-filter: blur(10px) !important;
  }

  #guide-content.ytd-app {
      background: rgba(0, 0, 0, 0.27) !important;
      backdrop-filter: blur(28px) !important;
      -webkit-backdrop-filter: blur(28px) !important;
  }

  .html5-video-player {
      border-radius: 1em !important;
  }
  .html5-video-player.ytp-fullscreen {
      border-radius: 0 !important;
  }
  
  #card.ytd-miniplayer {
      background-color: rgba(0, 0, 0, 0.51) !important;
      backdrop-filter: blur(28px) !important;
  }

  /* --- 5. RED ACCENTS & TOKEN FIXES --- */
  html[dark], [dark], :root {
      --yt-spec-brand-button-background: #ff0000 !important;
      --yt-button-color: #ff3636 !important;
      --yt-spec-brand-background-solid: #ff0000 !important;
      --yt-spec-static-brand-red: #ff0000 !important;
      --yt-spec-badge-chip-background: rgba(255, 255, 255, 0.1) !important;
  }

  path[fill="#FF0000"], path[fill="#ff0000"], circle[fill=red] {
      fill: #ff0000 !important;
  }

  /* FIXED: The comment submit button is visible and red again */
  #submit-button.ytd-commentbox yt-button-shape button,
  ytd-button-renderer.style-primary yt-button-shape button {
      background: #ff0000 !important;
      color: #ffffff !important;
      border-radius: 2em !important;
  }

  .yt-spec-icon-badge-shape--type-notification .yt-spec-icon-badge-shape__badge {
      background-color: #ff0000 !important;
  }

  /* --- 6. SMOOTH ENTRY ANIMATION (Replaces laggy BlurIn) --- */
  @keyframes SmoothIn {
    0%   { opacity: 0; transform: translateY(15px); }
    100% { opacity: 1; transform: translateY(0); }
  }

  #dismissible.ytd-rich-grid-media {
    animation: SmoothIn 0.5s cubic-bezier(0.16, 1, 0.3, 1) forwards !important;
    transform: translateZ(0); /* Forces GPU render */
    will-change: transform, opacity;
  }

  /* --- 7. YOUTUBE MUSIC PORT (Your exact specs) --- */
  ytmusic-app-layout[player-visible_] > [slot=player-bar], 
  ytmusic-app-layout[player-visible_] #player-bar-background.ytmusic-app-layout,
  #nav-bar-background.ytmusic-app-layout {
      background: linear-gradient(180deg, rgba(0,0,0,0.2), black) !important;
      backdrop-filter: blur(28px) !important;
  }

  ytmusic-app-layout[player-page-open_] > [slot=player-page] {
      backdrop-filter: blur(28px) !important;
      background: radial-gradient(transparent, #000000) !important;
  }

  .content-wrapper.ytmusic-play-button-renderer {
      backdrop-filter: blur(10px) !important;
      background: rgba(0, 0, 0, 0.25) !important;
      border: solid 1px rgba(197, 197, 197, 0.16) !important;
      box-shadow: 0px 0px 10px 0px rgba(0, 0, 0, 0.58) !important;
  }
}
